{
  "bioavailability_prediction": "low",
  "confidence": "high",
  "revision_action": "strengthen",
  "supportive_card_ids": ["C14","C15","C03","C04","C11","C17","C05","C06","C16","C18","C25","C27","C10"],
  "contradictory_card_ids": ["C24"],
  "prediction_basis_card_ids": ["C14","C15","C03","C04","C11","C17","C05"],
  "claims": [
    {
      "claim": "Salbutamol shares the query's saligenin head group and ethanolamine beta-agonist core and has measured oral bioavailability of 7.2% and 11.4% in fasting subjects, directly supporting F below 20% for the query.",
      "card_ids": ["C14","C15"]
    },
    {
      "claim": "Bambuterol, a beta-agonist of the same class, has oral bioavailability of about 10% in healthy adults, with L2 cards restating circa 10% and confirming oral availability.",
      "card_ids": ["C03","C04","C11","C25","C26"]
    },
    {
      "claim": "Epanolol, a related beta-amino alcohol, has absolute oral bioavailability of 5.85 ± 2.55% with food, and DHPG has absolute oral bioavailability of 5.4 ± 1.6% in humans.",
      "card_ids": ["C17","C05"]
    },
    {
      "claim": "Terfenadine, a lipophilic drug with extensive first-pass metabolism, has oral bioavailability below 5% in L1 and L2 records, supporting low F for lipophilic high-clearance molecules.",
      "card_ids": ["C06","C16","C18"]
    },
    {
      "claim": "Phenylephrine has poor and low-transient oral bioavailability, consistent with low F for phenylethanolamine-type drugs.",
      "card_ids": ["C10","C27"]
    },
    {
      "claim": "The only contradictory-direction L2 card reports hydroxytyrosol as highly bioavailable in rats, but this is qualitative, rat-specific, and contradicted by the human L1 value of 6.2% in the same context.",
      "card_ids": ["C24"]
    },
    {
      "claim": "I3C is described as low and highly variable with a 10-35% range that spans the 20% threshold, so it is ambiguous context rather than decisive evidence.",
      "card_ids": ["C22"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "associated_nonvoting_records",
      "applicability": "high",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C18","C19","C20","C21","C22","C23","C24","C25","C26","C27"]
    }
  ],
  "evidence_gaps": [
    "No direct oral bioavailability measurement exists for the query molecule.",
    "The long lipophilic dichlorobenzyl ether chain is not represented in any cited card and could alter permeability or first-pass metabolism relative to salbutamol.",
    "No card addresses the query's specific metabolic fate such as phenol conjugation or O-dealkylation.",
    "C22 reports a 10-35% range for I3C that spans the 20% threshold, leaving that context ambiguous."
  ],
  "decision_summary": "The query is a saligenin beta-agonist structurally closest to salbutamol, whose measured oral bioavailability is 7.2% and 11.4%; bambuterol (~10%), epanolol (5.85%), and DHPG (5.4%) reinforce the low-F family pattern. L2 adds terfenadine (<5%), phenylephrine (low and transient), and bambuterol (circa 10%) as supportive context, while the only contradictory-direction card (C24, rat hydroxytyrosol) is qualitative and species-mismatched. The query's near-complete ionization at pH 7.4 (neutral fraction 0.01) and 16 rotatable bonds further support F below 20%."
}

